INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】こうした効果を利用して、飲食店では食欲を刺激する暖色系の内装が用いられることが多い。
【B】色が人の心理に影響を与えることは、古くから経験的に知られてきた。
【C】つまり色彩は、空間の用途に応じて意図的に使い分けられる、実用的な心理的道具でもあるのである。
【D】例えば、暖色系の色は人の気分を高揚させ、寒色系の色は気持ちを落ち着かせる効果があるとされる。
【E】一方、病院や図書館のような落ち着きを求められる空間では、寒色系の色が選ばれる傾向にある。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで色彩が心理に影響を与えるという一般論を提示したのち、「例えば」で暖色・寒色の効果を具体的に説明するDが続く(B→D)。その暖色の応用例を挙げるAが続き(D→A)、「一方」で寒色の応用例を挙げるEが続く(A→E)。最後に「つまり」で色彩の実用性をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】この現象の主な原因の一つは、アスファルトやコンクリートが太陽熱を吸収し、夜間になってもその熱を放出し続けることにある。
【B】こうした状況に対応するため、建物の屋上を緑化したり、道路に保水性の高い舗装を採用したりする取り組みが進められている。
【C】都市部の気温が、周辺の郊外や自然が多い地域よりも高くなる現象を、ヒートアイランド現象と呼ぶ。
【D】このように都市の暑さへの対策は、緑や水の力を都市機能のなかに取り戻す方向へと向かいつつある。
【E】また、建物や自動車から排出される人工排熱も、都市の気温上昇に拍車をかけている。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで現象の定義を示したのち、原因の一つを説明するAが続く(C→A)。「また」で別の原因を付け加えるEが続き(A→E)、「こうした状況に対応するため」と対策を述べるBが続く(E→B)。最後に「このように」として対策の方向性をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】ワクチンは、この記憶の仕組みを人為的に利用し、あらかじめ免疫に病原体の情報を覚えさせる技術だといえる。
【B】そして、その病原体の特徴を記憶し、それに応じた抗体を作り出すことで、攻撃を仕掛ける。
【C】病原体が体内に侵入すると、免疫細胞はまずその存在を異物として認識する。
【D】一度記憶された病原体の情報は、体内に長く保持されるため、同じ病原体が再び侵入した際には、より迅速に対応できるようになる。
【E】私たちの体には、外部から侵入した病原体を排除する、免疫と呼ばれる防御の仕組みが備わっている。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで免疫という仕組みの存在を示したのち、病原体侵入時の最初の反応を述べるCが続く(E→C)。「そして」記憶と抗体生成を述べるBが続き(C→B)、その記憶が長く保持されることを述べるDが続く(B→D)。最後にワクチンの仕組みへの応用を述べるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】このように、情報の切り取り方や表現の枠組みによって受け手の判断が左右される現象を、フレーミング効果と呼ぶ。
【B】例えば、「手術の成功率は九十パーセントです」と伝えるのと、「手術の失敗率は十パーセントです」と伝えるのとでは、示している事実は同じである。
【C】にもかかわらず、多くの人は前者の表現を聞いたほうが、より安心感を抱く傾向にある。
【D】同じ内容の情報であっても、表現の仕方によって、受け手の印象が大きく変わることがある。
【E】広告の分野では、この効果を踏まえ、同じ事実であってもより好意的に受け取られる表現が意図的に選ばれることが多い。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで表現による印象の違いという主題を提示したのち、「例えば」で具体例を挙げるBが続く(D→B)。「にもかかわらず」でその心理的な傾向を述べるCが続き(B→C)、「このように」と現象に名前をつけるAが続く(C→A)。最後に広告分野での応用を述べるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】建物の設計において、自然光をどのように室内に取り込むかという採光の計画は、快適な居住環境を左右する重要な要素である。
【B】つまり優れた採光設計とは、単に光を取り入れる量を増やすことではなく、方角ごとの光の性質を見極めたうえで調整することなのである。
【C】そのため、方角に応じて窓の大きさやひさしの形状を工夫することが求められる。
【D】例えば、南向きの窓からは一日を通して安定した光が入りやすいが、西向きの窓からは夕方に強い日差しが差し込み、室温の上昇を招きやすい。
【E】単に窓を大きくすればよいというわけではなく、方角によって差し込む光の性質は大きく異なる。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで採光計画の重要性を提示したのち、方角によって光の性質が異なると述べるEが続く(A→E)。「例えば」で具体例を挙げるDが続き(E→D)、「そのため」と対応する工夫を述べるCが続く(D→C)。最後に「つまり」として採光設計の本質をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】例えば、周囲の環境に溶け込みやすい体色を持つ個体は、捕食者に見つかりにくく、生き残る確率が高くなる。
【B】生物の進化を説明する代表的な理論の一つに、自然選択という考え方がある。
【C】このように自然選択は、個々の生物が意図的に変化するのではなく、生存に有利な特徴が結果として集団のなかに広がっていく過程だといえる。
【D】自然選択とは、ある環境において生存や繁殖に有利な特徴を持つ個体が、より多くの子孫を残しやすくなるという仕組みである。
【E】こうした個体が世代を重ねるごとに増えていくことで、集団全体の特徴が、環境に適した方向へと徐々に変化していく。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで自然選択という理論を提示したのち、その定義を説明するDが続く(B→D)。「例えば」で具体例を挙げるAが続き(D→A)、その個体が世代を重ねて増えていく過程を述べるEが続く(A→E)。最後に「このように」として自然選択の本質をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】経済学では、この考え方を比較優位と呼ぶ。
【B】重要なのは、絶対的な生産性の高さではなく、自国内で他の産業と比べて、相対的にどの産業が得意かという点である。
【C】二つの国のあいだで貿易を行う際、それぞれの国が得意とする分野に集中して生産する方が、双方にとって利益が大きくなる場合がある。
【D】つまり貿易における利益は、各国が最も得意な分野に生産を集中させ、それぞれの成果を交換し合うことによって生まれるのである。
【E】興味深いのは、ある国があらゆる産業において他国より高い生産性を持っていたとしても、比較優位の考え方は成り立つという点である。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで貿易における分業の利益を提示したのち、その考え方に名前をつけるAが続く(C→A)。「興味深いのは」と例外的な性質を述べるEが続き(A→E)、その理由となる相対的な得意分野の重要性を述べるBが続く(E→B)。最後に「つまり」で貿易利益の本質をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】つまり語族という考え方は、現在の多様な言語のなかに、過去の人々の移動や交流の痕跡を読み取るための手がかりを与えてくれるのである。
【B】このようなまとまりは語族と呼ばれ、例えば英語やフランス語、ヒンディー語などは、インド・ヨーロッパ語族という同じ系統に属するとされている。
【C】語彙や文法の類似性を手がかりに言語同士の関係をたどっていくと、共通の祖先となる言語から枝分かれしてきたと考えられる言語のまとまりが見えてくる。
【D】同じ語族に属する言語は、見た目には大きく異なって見えても、数字の数え方や基本的な単語に共通点が見られることがある。
【E】世界中には数千とも言われる言語が存在するが、そのすべてがばらばらに生まれたわけではない。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで言語が無関係に生まれたわけではないと提示したのち、語彙や文法の類似性から言語のまとまりが見えてくると述べるCが続く(E→C)。そのまとまりを語族と名付け具体例を挙げるBが続き(C→B)、共通点についてさらに述べるDが続く(B→D)。最後に「つまり」として語族という考え方の意義をまとめるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】情報を脳から積極的に引き出そうとする過程そのものが、記憶を強化する働きを持つと考えられている。
【B】しかし近年の研究では、読み返すことよりも、学んだ内容を思い出そうとする練習、いわゆる検索練習の方が、記憶の定着に効果的であることが分かってきた。
【C】例えば、教科書を読んだ後に問題を解いたり、内容を何も見ずに書き出したりする行為は、この検索練習にあたる。
【D】学習の効果を高める方法として、教科書を何度も読み返すことが一般的に行われている。
【E】したがって効果的な学習のためには、覚えることに時間をかけるだけでなく、思い出す機会を意図的に作ることが重要なのである。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで教科書の読み返しという一般的な学習法を提示したのち、「しかし」で検索練習の方が効果的だと転換するBが続く(D→B)。「例えば」で具体例を挙げるCが続き(B→C)、その効果の理由を説明するAが続く(C→A)。最後に「したがって」として効果的な学習法をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】天気予報は、気象観測技術の進歩によって精度を高めてきたが、それでも遠い将来の天気を正確に予測することは難しい。
【B】つまり天気予報の限界は、観測技術の未熟さだけでなく、大気そのものが持つ本質的な性質に由来するのである。
【C】大気の状態も同様に、観測誤差というごくわずかなずれが、日数が経つにつれて予測結果に大きな影響を及ぼすようになる。
【D】カオス理論とは、初期の状態にごくわずかな違いがあるだけで、時間が経つにつれてその違いが大きく増幅され、全く異なる結果を生み出すという性質を指す。
【E】この背景には、大気の状態が、カオス理論と呼ばれる性質を持っているという事情がある。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで天気予報の限界を提示したのち、その背景にカオス理論があると述べるEが続く(A→E)。カオス理論の定義を説明するDが続き(E→D)、それを大気の状態に当てはめるCが続く(D→C)。最後に「つまり」として天気予報の限界の本質をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】コンパクトシティとは、住宅や商業施設、行政サービスといった都市機能を、駅の周辺など特定の範囲に集約させる都市設計の考え方である。
【B】人口減少や高齢化が進む地域では、都市機能をどのように維持していくかが大きな課題となっている。
【C】このようにコンパクトシティは、人口減少という制約のなかで、生活の利便性と行政の効率性を両立させようとする発想なのである。
【D】この課題への対応策の一つとして、コンパクトシティという都市の形が注目されている。
【E】機能を集約することで、住民は徒歩や公共交通機関で日常の用事を済ませやすくなり、行政にとっても道路や上下水道といったインフラの維持費用を抑えることができる。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで都市機能維持という課題を提示したのち、「この課題への対応策の一つとして」とコンパクトシティを紹介するDが続く(B→D)。その定義を説明するAが続き(D→A)、集約による利点を述べるEが続く(A→E)。最後に「このように」として発想の本質をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】縄張りを持つことで、その範囲内にある餌や繁殖の相手といった資源を、他の個体と争うことなく独占できるという利点がある。
【B】そのため、縄張りの大きさは、得られる資源の量と、維持にかかる労力とのバランスによって決まると考えられている。
【C】多くの動物は、自分が生活する一定の範囲を縄張りとして持ち、他の個体の侵入を排除しようとする。
【D】つまり縄張り行動とは、資源の独占という利益と、維持にかかるコストとを天秤にかけたうえで成立している行動だといえる。
【E】一方で、縄張りを維持するためには、常に周囲を見張り、侵入者を追い払うための労力やエネルギーが必要になる。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで縄張りを持つ動物の行動を提示したのち、その利点を述べるAが続く(C→A)。「一方で」維持のコストを述べるEが続き(A→E)、「そのため」と縄張りの大きさが決まる要因を述べるBが続く(E→B)。最後に「つまり」として縄張り行動の本質をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】つまり著作権制度とは、作者の権利を保護すると同時に、新たな創作活動を社会全体で促していくための仕組みでもあるのである。
【B】著作権によって作品の利用が制限されることで、作者は自らの創作物から収入を得る機会を確保できるようになる。
【C】もし誰もが自由に他者の作品を複製し、利益を得られるとしたら、作者自身は創作活動によって十分な対価を得ることが難しくなってしまう。
【D】この仕組みがあることで、創作活動に多くの時間や労力を費やすことへの動機づけが生まれる。
【E】小説や音楽、絵画といった創作物には、その作者に一定期間、独占的な利用権を認める著作権という制度が設けられている。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで著作権制度の存在を提示したのち、「もし」制度がなかった場合の弊害を述べるCが続く(E→C)。それを踏まえ、実際の制度による収入確保を述べるBが続き(C→B)、その仕組みによる動機づけを述べるDが続く(B→D)。最後に「つまり」として制度の意義をまとめるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】一方で、俳優が観客に直接話しかけたり、客席に足を踏み入れたりすることで、あえてこの壁を壊す演出が用いられることもある。
【B】これは第四の壁と呼ばれ、俳優は観客の存在を意識していないかのように振る舞い、あたかも独立した物語の世界がそこにあるかのように演じる。
【C】観客は、この壁の存在によって、舞台上の出来事を、自分とは切り離された物語として安心して眺めることができる。
【D】演劇の舞台には、客席と舞台のあいだに、目には見えない仮想の壁が存在するという考え方がある。
【E】このように第四の壁を壊す演出は、観客に物語との距離を意識させ、日常とは異なる緊張感や新鮮さをもたらす効果を持つのである。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで仮想の壁という考え方を提示したのち、その名称と俳優の振る舞いを説明するBが続く(D→B)。観客側から見た効果を述べるCが続き(B→C)、「一方で」あえて壁を壊す演出があると述べるAが続く(C→A)。最後に「このように」としてその演出の効果をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】私たちの腸のなかには、数百種類にも及ぶ細菌が生息しており、これらの集まりは腸内フローラと呼ばれている。
【B】このことから、腸内環境を整えることは、体全体の健康を維持するうえで、見過ごすことのできない要素として注目されるようになっている。
【C】近年の研究では、腸内フローラのバランスが、消化器官だけでなく、免疫の働きや気分の状態にまで影響を及ぼしている可能性が指摘されている。
【D】つまり腸内の細菌は、単なる同居者ではなく、私たちの健康維持に積極的に関わる存在だといえる。
【E】腸内フローラを構成する細菌のなかには、食物の消化を助けたり、体に有害な物質を作る菌の増殖を抑えたりする働きを持つものが含まれている。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで腸内フローラの定義を提示したのち、細菌の働きを説明するEが続く(A→E)。「つまり」とその意義をまとめるDが続き(E→D)、近年の研究知見を述べるCが続く(D→C)。最後に「このことから」として腸内環境を整える重要性をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】例えば、交渉の場において、最初に高い金額が提示されると、その後に多少値引きされた金額であっても、割安に感じられやすくなる。
【B】人が何かの価値を判断する際、最初に提示された数値の影響を強く受けてしまうことが知られている。
【C】このためアンカリング効果は、交渉術の一つとして意図的に利用されることも少なくない。
【D】これはアンカリング効果と呼ばれ、最初の数値が、その後の判断の基準点、すなわち錨として働くことに由来する名称である。
【E】本来であれば、提示された金額の妥当性を、その都度冷静に検討するべきであるにもかかわらず、最初の数値がその後の判断を歪めてしまうのである。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで最初の数値の影響という現象を提示したのち、その現象に名前をつけるDが続く(B→D)。「例えば」で具体例を挙げるAが続き(D→A)、その判断の歪みを説明するEが続く(A→E)。最後に「このため」として交渉術への応用をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】伝統的な木造建築のなかには、あえて建物全体を固めすぎず、地震の揺れを受け流すような構造が採用されているものがある。
【B】これは、力に真っ向から抵抗する構造とは異なり、揺れをしなやかに受け流すという発想に基づいている。
【C】日本は地震が多い国であり、建物の耐震性は古くから重要な課題とされてきた。
【D】つまり伝統的な木造建築の耐震性とは、建物を頑丈に固めることではなく、揺れに柔軟に対応する構造によって支えられてきたのである。
【E】例えば、柱や梁の接合部分にわずかな遊びを持たせることで、地震のエネルギーを建物全体に分散させ、一部分に力が集中することを防ぐ工夫が見られる。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで日本の耐震性の課題を提示したのち、揺れを受け流す伝統構造の存在を述べるAが続く(C→A)。「例えば」で具体的な工夫を挙げるEが続き(A→E)、その発想の本質を説明するBが続く(E→B)。最後に「つまり」として木造建築の耐震性の本質をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】このように相関関係と因果関係を混同しないことは、データを正しく読み解くうえで欠かせない視点なのである。
【B】例えば、ある町でアイスクリームの売り上げと水難事故の件数が、同じ時期に増加するというデータが得られたとする。
【C】しかし、二つの事柄が同時に増減する関係、すなわち相関関係が見られたとしても、それが直ちに一方が他方の原因であることを意味するわけではない。
【D】この場合、アイスクリームの売り上げが水難事故を引き起こしているのではなく、気温の上昇という共通の原因が、両方の増加をもたらしていると考える方が自然である。
【E】統計データを分析していると、二つの事柄のあいだに関連性が見られることがある。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで関連性が見られるという一般的な話を提示したのち、「しかし」で相関と因果を混同すべきでないと注意を促すCが続く(E→C)。「例えば」で具体例を挙げるBが続き(C→B)、その解釈を述べるDが続く(B→D)。最後に「このように」として全体をまとめるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】このように手話には、音声言語における抑揚やイントネーションに相当する要素が、身体の動きのなかに組み込まれている。
【B】手の動きや形だけでなく、表情や視線の動きも、意味を伝えるうえで重要な役割を果たしている。
【C】例えば、同じ手の動きであっても、眉の上げ下げによって疑問文であるか肯定文であるかが区別される場合がある。
【D】手話は、単なる身振りや身体表現ではなく、独自の文法体系を持った、音声言語と対等な一つの言語である。
【E】つまり手話とは、音声とは異なる感覚を通じて情報を伝える、体系立った独立した言語だといえるのである。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで手話が独自の文法体系を持つ言語だと提示したのち、表情や視線の役割を述べるBが続く(D→B)。「例えば」で具体例を挙げるCが続き(B→C)、「このように」とその要素をまとめるAが続く(C→A)。最後に「つまり」として手話という言語の本質をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】ミツバチは、仲間に対して、蜜のある場所の情報を伝える独特な行動をとることが知られている。
【B】つまり8の字ダンスとは、視覚的な動作によって、位置という抽象的な情報を仲間に伝達する、ミツバチ独自のコミュニケーション手段なのである。
【C】仲間のミツバチは、このダンスを観察することで、実際にその場所を訪れることなく、蜜源の位置を把握することができる。
【D】ダンスの向きは太陽の位置を基準とした蜜源の方角を、体を震わせる時間の長さは巣からの距離を表しているとされる。
【E】この行動は8の字を描くように体を動かすことから、8の字ダンスと呼ばれている。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aでミツバチの情報伝達行動を提示したのち、その行動の名称を説明するEが続く(A→E)。ダンスの向きや時間が持つ意味を説明するDが続き(E→D)、その情報を仲間が読み取れると述べるCが続く(D→C)。最後に「つまり」として8の字ダンスの本質をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
